-- Recuperada da producao (supabase_migrations.schema_migrations).
--
-- Esta migration JA ESTA APLICADA no banco de producao, mas nao tinha arquivo
-- no repositorio: o check "Supabase Preview" falhava em todo push para a main
-- com "Remote migration versions not found in local migrations directory",
-- e a cadeia local nao reconstruia a producao.
--
-- O SQL abaixo e o que a propria producao registrou ter executado.
-- versao: 20260321125811
-- nome:   salespro_mig_005_gamification

CREATE TABLE IF NOT EXISTS public.achievements (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, achievement_type TEXT NOT NULL DEFAULT 'daily_goal', achievement_date DATE NOT NULL DEFAULT CURRENT_DATE, details JSONB DEFAULT '{}', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.salesperson_xp (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL UNIQUE REFERENCES public.salespeople(id) ON DELETE CASCADE, total_xp INTEGER NOT NULL DEFAULT 0, current_level INTEGER NOT NULL DEFAULT 1, xp_to_next_level INTEGER NOT NULL DEFAULT 100, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.xp_history (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, xp_amount INTEGER NOT NULL, source_type TEXT NOT NULL, source_id TEXT, description TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.weekly_challenges (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, title TEXT NOT NULL, description TEXT, challenge_type TEXT NOT NULL DEFAULT 'activity', target_value INTEGER NOT NULL DEFAULT 10, xp_reward INTEGER NOT NULL DEFAULT 100, start_date DATE NOT NULL, end_date DATE NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.challenge_progress (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, challenge_id UUID NOT NULL REFERENCES public.weekly_challenges(id) ON DELETE CASCADE, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, current_value INTEGER NOT NULL DEFAULT 0, completed_at TIMESTAMP WITH TIME ZONE, xp_claimed BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(challenge_id, salesperson_id));
CREATE TABLE IF NOT EXISTS public.daily_challenges (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, title TEXT NOT NULL, description TEXT, challenge_type TEXT NOT NULL DEFAULT 'calls', target_value INTEGER NOT NULL DEFAULT 5, xp_reward INTEGER NOT NULL DEFAULT 25, challenge_date DATE NOT NULL DEFAULT CURRENT_DATE, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.daily_challenge_progress (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, challenge_id UUID NOT NULL REFERENCES public.daily_challenges(id) ON DELETE CASCADE, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, current_value INTEGER NOT NULL DEFAULT 0, completed_at TIMESTAMP WITH TIME ZONE, xp_claimed BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(challenge_id, salesperson_id));
CREATE TABLE IF NOT EXISTS public.daily_streak_achievements (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id uuid NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, streak_type text NOT NULL, achieved_at timestamp with time zone NOT NULL DEFAULT now(), streak_count integer NOT NULL, xp_awarded integer NOT NULL DEFAULT 0, created_at timestamp with time zone NOT NULL DEFAULT now(), UNIQUE(salesperson_id, streak_type));
CREATE TABLE IF NOT EXISTS public.collectible_badges (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, icon TEXT NOT NULL DEFAULT 'trophy', category TEXT NOT NULL DEFAULT 'achievement', rarity TEXT NOT NULL DEFAULT 'common' CHECK (rarity IN ('common','rare','epic','legendary')), requirement_type TEXT NOT NULL, requirement_value INTEGER NOT NULL DEFAULT 1, xp_reward INTEGER NOT NULL DEFAULT 50, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.salesperson_badges (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, badge_id UUID NOT NULL REFERENCES public.collectible_badges(id) ON DELETE CASCADE, earned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), is_displayed BOOLEAN NOT NULL DEFAULT true, UNIQUE(salesperson_id, badge_id));
CREATE TABLE IF NOT EXISTS public.progressive_goals (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, goal_type TEXT NOT NULL, current_tier INTEGER NOT NULL DEFAULT 1, current_value NUMERIC NOT NULL DEFAULT 0, tier_target NUMERIC NOT NULL, completed_tiers JSONB DEFAULT '[]'::jsonb, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(salesperson_id, goal_type));
CREATE TABLE IF NOT EXISTS public.victory_feed (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, event_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT, xp_earned INTEGER DEFAULT 0, metadata JSONB DEFAULT '{}', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.feed_reactions (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, feed_item_id UUID NOT NULL REFERENCES public.victory_feed(id) ON DELETE CASCADE, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, reaction_type TEXT NOT NULL DEFAULT 'like', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(feed_item_id, salesperson_id));
CREATE TABLE IF NOT EXISTS public.feed_comments (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, feed_item_id UUID NOT NULL REFERENCES public.victory_feed(id) ON DELETE CASCADE, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());

ALTER TABLE public.achievements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.salesperson_xp ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.xp_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.weekly_challenges ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.daily_challenges ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.collectible_badges ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.victory_feed ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN CREATE POLICY "achievements_all" ON public.achievements FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "xp_all" ON public.salesperson_xp FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "xp_history_all" ON public.xp_history FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "challenges_all" ON public.weekly_challenges FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "daily_challenges_all" ON public.daily_challenges FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "badges_all" ON public.collectible_badges FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "victory_all" ON public.victory_feed FOR ALL USING (true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
